const platformInfo={arduino:{board:'Arduino Uno / Nano',controller:'ATmega328P',parts:['Arduino Uno or Nano','HC-SR04 ultrasonic sensor','L298N motor driver','2 DC gear motors','Battery pack and jumper wires'],code:`const int trigPin = 9;\nconst int echoPin = 10;\nconst int motorA = 5;\nvoid setup(){ pinMode(trigPin,OUTPUT); pinMode(echoPin,INPUT); pinMode(motorA,OUTPUT); Serial.begin(9600); }\nvoid loop(){\n  digitalWrite(trigPin,LOW); delayMicroseconds(2);\n  digitalWrite(trigPin,HIGH); delayMicroseconds(10); digitalWrite(trigPin,LOW);\n  long duration=pulseIn(echoPin,HIGH); int cm=duration*0.034/2;\n  analogWrite(motorA, cm>20 ? 150 : 0); delay(50);\n}`},esp:{board:'ESP32 / NodeMCU (ESP8266)',controller:'ESP32 or ESP8266',parts:['ESP32 DevKit or NodeMCU board','Ultrasonic distance sensor','Motor driver module','2 DC gear motors','Battery pack and jumper wires'],code:`const int trigPin=5, echoPin=18, motorA=19;\nvoid setup(){ pinMode(trigPin,OUTPUT); pinMode(echoPin,INPUT); pinMode(motorA,OUTPUT); Serial.begin(115200); }\nvoid loop(){\n  digitalWrite(trigPin,LOW); delayMicroseconds(2);\n  digitalWrite(trigPin,HIGH); delayMicroseconds(10); digitalWrite(trigPin,LOW);\n  long duration=pulseIn(echoPin,HIGH,30000); int cm=duration*0.034/2;\n  digitalWrite(motorA, cm>20 ? HIGH : LOW); delay(50);\n}`},pi:{board:'Raspberry Pi',controller:'Linux SBC / Python',parts:['Raspberry Pi with power supply','Distance sensor (use a safe 3.3V level interface)','Motor driver module','2 DC gear motors','Wheels, chassis, and jumper wires'],code:`from gpiozero import DistanceSensor, Motor\nfrom time import sleep\nsensor = DistanceSensor(echo=24, trigger=23, max_distance=2)\nmotor = Motor(forward=17, backward=18, enable=12)\ntry:\n    while True:\n        if sensor.distance > 0.20:\n            motor.forward(0.55)\n        else:\n            motor.stop()\n        sleep(0.05)\nfinally:\n    motor.stop()`},custom:{board:'Aether Core concept',controller:'Your selected MCU architecture',parts:['Aether Core concept board specification','Distance sensor with voltage compatibility checked','Motor driver matched to the chosen MCU','2 DC gear motors and a suitable battery','USB programming path, regulators, protection, and test points'],code:`// Aether Core starter sketch (architecture to be selected)\n// Confirm voltage, pin mapping, and board support before wiring.\nconst int TRIG_PIN = /* assign in pin map */;\nconst int ECHO_PIN = /* assign in pin map */;\nconst int MOTOR_EN = /* assign in pin map */;\nvoid setup() {\n  Serial.begin(115200);\n  // Initialize GPIO using the selected MCU framework.\n}\nvoid loop() {\n  // Read distance, check safety limits, then control motor driver.\n}`}}; const projectTypes={sensor:{label:'Sensor & environment',parts:['Temperature / humidity sensor','Breadboard and jumper wires','Controller board','USB cable or suitable battery'],goal:'Read an environmental sensor and display or log its values.'},automation:{label:'Home automation',parts:['Relay module rated for the load','Controller board','Switch or sensor input','Isolated, suitable power supply'],goal:'Use a sensor or switch to trigger a low-voltage automation.'},robot:{label:'Mobile robot',parts:['Distance sensor','Motor driver','2 DC gear motors','Chassis, wheels, and battery'],goal:'Build a small robot that reacts to its surroundings.'},vision:{label:'Camera / computer vision',parts:['Camera module','Controller with camera support','Stable power supply','Mount or small pan-tilt bracket'],goal:'Capture images and prototype a simple vision workflow.'},custom:{label:'Custom robotics project',parts:['Controller board','Inputs and sensors for your goal','Outputs or actuators','Power source matched to your components'],goal:'Write down one behavior, then break it into input, logic, and output.'}};
let latestCode='',latestPlan='';document.querySelector('#project-form').addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#project-name').value.trim()||'New robotics project';const boardKey=document.querySelector('#board').value;const typeKey=document.querySelector('#project-type').value;const skill=document.querySelector('#skill').value;const goal=document.querySelector('#goal').value.trim();const b=platformInfo[boardKey],t=projectTypes[typeKey];const parts=[...new Set([...t.parts,...b.parts.slice(0,2)])];const depth=skill==='beginner'?'Start with one sensor and confirm each connection before adding motors.':skill==='intermediate'?'Prototype the sensor and motor subsystems separately, then integrate them.':'Add error handling, power monitoring, and a repeatable test plan before integration.';latestCode=b.code;latestPlan=`${name}\nBoard: ${b.board}\nProject: ${t.label}\nGoal: ${goal||t.goal}\n\nStarter parts:\n${parts.map(x=>'- '+x).join('\n')}\n\nFirst steps:\n1. Draw the power and signal connections; check voltage levels.\n2. Test each input and output independently.\n3. ${depth}\n4. Add the main behavior and test it in a safe, small setup.\n\nController: ${b.controller}`;document.querySelector('#blueprint').innerHTML=`<div class="blueprint-result"><div><span class="result-kicker">PROJECT BLUEPRINT / ${esc(b.board.toUpperCase())}</span><h3>${esc(name)}</h3><p>${esc(goal||t.goal)}</p><p><b>Platform:</b> ${esc(b.board)} · ${esc(b.controller)}</p><span class="result-kicker">STARTER PARTS</span><ul class="result-list">${parts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><span class="result-kicker">FIRST BUILD STEPS</span><ol class="result-list"><li>Sketch the wiring and verify power and logic levels.</li><li>Test one sensor and one output at a time.</li><li>${esc(depth)}</li><li>Integrate, test safely, and document what changed.</li></ol></div><div><span class="result-kicker">CODE STARTER / ${boardKey==='pi'?'PYTHON':'C++-STYLE'}</span><div class="code-box"><pre>${esc(b.code)}</pre></div></div></div>`;document.querySelector('#blueprint-actions').hidden=false;document.querySelector('#copy-status').textContent=''});
document.querySelector('#copy-code').addEventListener('click',async()=>copyText(latestCode,'Starter code copied.'));document.querySelector('#copy-plan').addEventListener('click',async()=>copyText(latestPlan,'Project plan copied.'));async function copyText(text,msg){try{await navigator.clipboard.writeText(text);document.querySelector('#copy-status').textContent=msg}catch{document.querySelector('#copy-status').textContent='Select and copy from the blueprint.'}}
document.querySelector('#save-board').addEventListener('click',()=>{const title=document.querySelector('#board-name').value.trim()||'New board concept';const goal=document.querySelector('#board-goal').value.trim();try{localStorage.setItem('innocad-board-'+title,JSON.stringify({title,goal,updated:new Date().toISOString()}));document.querySelector('#board-status').textContent=`“${title}” saved in this browser. Add MCU, power, pin, programming, and protection decisions next.`}catch{document.querySelector('#board-status').textContent='This browser could not save the board concept.'}});function esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}
